/** @jsxImportSource kerfjs */
import { delegate } from 'kerfjs';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarText } from '@kerfjs/ui/toolbar-text';
import { ToolbarControlGroup } from '@kerfjs/ui/toolbar-control-group';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { PageHeader } from '@kerfjs/ui/page-header';
import { ValueTable } from '@kerfjs/ui/value-table';
import { ResizableRegion } from '@kerfjs/ui/resizable-region';
import { wireResizableRegions } from '@kerfjs/ui/wire-resizable-regions';
import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/sidebar.css';
import './application-shell.css';

type Pane = 'navigation' | 'workspace' | 'inspector';
type Section = 'inbox' | 'projects' | 'drafts';
type Task = { id: string; title: string; owner: string; status: string };
export interface ShellOptions {
  id: string;
  tasks: Task[];
  loadInspectorWidth(): number | null;
  saveInspectorWidth(width: number): void;
  onAction(action: 'task.create' | 'workspace.navigate', value?: string): void;
}
// The host mounts render() with its Kerf renderer and passes a synchronous
// invalidator to connect(). All state and persistence belong to this instance.
export function createApplicationShell(options: ShellOptions) {
  let section: Section = 'inbox';
  let phonePane: Pane = 'workspace';
  const saved = options.loadInspectorWidth();
  let inspectorWidth = saved != null && Number.isFinite(saved)
    ? Math.max(200, Math.min(360, saved)) : 260;
  const prefix = options.id;
  const navigation = () => <aside class="shell-navigation" aria-label="Navigation">
    <nav class="kui-sidebar kui-scroll-owner shell-nav-body" aria-label="Workspace sections" tabindex="0">
      <section class="kui-sidebar-section">
        <MenuHeader label="Workspace" />
        <MenuItem action="workspace.navigate" itemId="inbox" label="Inbox" selected={section === 'inbox'} />
        <MenuItem action="workspace.navigate" itemId="projects" label="Projects" selected={section === 'projects'} />
      </section>
      <section class="kui-sidebar-section">
        <MenuHeader label="Personal" />
        <MenuItem action="workspace.navigate" itemId="drafts" label="Drafts" selected={section === 'drafts'} />
      </section>
    </nav>
  </aside>;
  const inspector = () => <aside class="shell-inspector" aria-label="Inspector">
    <h2 class="shell-inspector-title">Inspector</h2>
    <div class="kui-scroll-owner kui-pane-body" tabindex="0" aria-label="Inspector details">
      <ValueTable label="Workspace details">
        <div><dt>Section</dt><dd>{section}</dd></div>
        <div><dt>Tasks</dt><dd>{options.tasks.length}</dd></div>
      </ValueTable>
    </div>
  </aside>;
  const render = () => <section class="app-shell kui-layout" data-phone-pane={phonePane}>
    <Toolbar label="Workspace toolbar" leading={<ToolbarText text="Atlas" />} trailing={
      <ToolbarControlGroup appearance="borderless" label="Workspace panes">
        <button type="button" data-action="shell.pane" data-pane="navigation" aria-controls={prefix + '-navigation'} aria-label="Show navigation">Navigation</button>
        <button type="button" data-action="shell.pane" data-pane="workspace" aria-controls={prefix + '-workspace'}>Workspace</button>
        <button type="button" data-action="shell.pane" data-pane="inspector" aria-controls={prefix + '-inspector'} aria-label="Show inspector">Inspector</button>
      </ToolbarControlGroup>
    } />
    <div class="app-shell-body">
      <div id={prefix + '-navigation'} class="shell-navigation-region" tabindex="-1">{navigation()}</div>
      <main id={prefix + '-workspace'} class="shell-workspace" tabindex="-1">
        <PageHeader title={section === 'inbox' ? 'Inbox' : section === 'projects' ? 'Projects' : 'Drafts'}
          action={<button class="shell-button" type="button" data-action="task.create">New task</button>} />
        <div class="kui-scroll-owner kui-pane-body kui-section-stack" tabindex="0" aria-label="Workspace tasks">
          {options.tasks.length ? options.tasks.map(task => <article class="shell-card kui-surface-body">
            <h2>{task.title}</h2>
            <p class="kui-inline-metadata"><span>{task.status}</span><span>Owner: {task.owner}</span></p>
          </article>) : <p>No tasks in this workspace.</p>}
        </div>
      </main>
      <div id={prefix + '-inspector'} class="shell-inspector-region" tabindex="-1">
        <ResizableRegion id={prefix + '-resize'} label="Inspector width" size={inspectorWidth} min={200} max={360} edge="start">
          {inspector()}
        </ResizableRegion>
      </div>
    </div>
  </section>;
  function connect(root: HTMLElement, invalidate: () => void) {
    const actions = delegate(root, 'click', '[data-action]', (_event, element) => {
      const action = element.getAttribute('data-action');
      if (action === 'shell.pane') {
        const pane = element.getAttribute('data-pane');
        if (pane !== 'navigation' && pane !== 'workspace' && pane !== 'inspector') return;
        phonePane = pane;
        invalidate();
        root.querySelector<HTMLElement>('#' + CSS.escape(prefix + '-' + pane))?.focus();
      }
      if (action === 'workspace.navigate') {
        const id = element.getAttribute('data-item-id');
        if (id !== 'inbox' && id !== 'projects' && id !== 'drafts') return;
        section = id;
        phonePane = 'workspace';
        options.onAction('workspace.navigate', id);
        invalidate();
        root.querySelector<HTMLElement>('#' + CSS.escape(prefix + '-workspace'))?.focus();
      }
      if (action === 'task.create') options.onAction('task.create');
    });
    const resize = wireResizableRegions(root, {
      onResize: (id, size) => {
        if (id !== prefix + '-resize') return;
        inspectorWidth = Math.max(200, Math.min(360, size));
        invalidate();
      },
      onResizeEnd: (id, size) => {
        if (id !== prefix + '-resize') return;
        inspectorWidth = Math.max(200, Math.min(360, size));
        options.saveInspectorWidth(inspectorWidth);
        invalidate();
      },
    });
    return () => { actions(); resize(); };
  }
  return { render, connect };
}

