.app-shell { display:grid; grid-template-rows:auto minmax(0,1fr); height:100dvh; min-width:0; overflow:hidden; color:var(--kui-color-text); background:var(--kui-color-surface); }
.app-shell-body { display:flex; min-height:0; min-width:0; }
.shell-navigation-region { flex:0 0 14rem; min-height:0; }
.shell-navigation { height:100%; min-height:0; display:grid; grid-template-rows:minmax(0,1fr); }
.shell-nav-body { padding-block:var(--kui-layout-pane-inset); }
.shell-workspace { flex:1; min-width:0; min-height:0; display:grid; grid-template-rows:auto minmax(0,1fr); background:var(--kui-color-surface-lowered); }
.shell-inspector-region { min-height:0; display:flex; }
.shell-inspector { min-height:0; height:100%; display:grid; grid-template-rows:auto minmax(0,1fr); }
.shell-inspector-title { margin:0; padding:var(--kui-layout-pane-inset); font-size:var(--kui-font-l); border-block-end:1px solid var(--kui-color-border); }
.shell-card { border:1px solid var(--kui-color-border); border-radius:var(--kui-radius-m); background:var(--kui-color-surface); overflow-wrap:anywhere; }
.shell-card h2 { margin:0; font-size:var(--kui-font-l); }
.shell-button { font:inherit; padding:var(--kui-space-xs) var(--kui-space-s); min-height:2.75rem; color:var(--kui-color-brand-on-normal); background:var(--kui-color-brand-fill-normal); border:1px solid var(--kui-color-brand-border-normal); border-radius:var(--kui-radius-m); }
.app-shell :focus-visible { outline:var(--kui-focus-ring); outline-offset:2px; }
@media(max-width:60rem) {
  .app-shell-body > * { display:none; }
  .app-shell[data-phone-pane="navigation"] .shell-navigation-region { display:block; flex:1; }
  .app-shell[data-phone-pane="workspace"] .shell-workspace { display:grid; }
  .app-shell[data-phone-pane="inspector"] .shell-inspector-region { display:flex; flex:1; }
  .shell-inspector-region { --kui-resizable-region-size:100% !important; }
  .shell-inspector-region .kui-resizable-region { width:100% !important; flex:1; }
  .shell-inspector-region .kui-resizable-region__handle { display:none; }
  .app-shell .kui-toolbar { height:auto; grid-template-columns:minmax(0,1fr); gap:var(--kui-layout-control-gap); }
  .app-shell .kui-toolbar__trailing { justify-content:flex-start; flex-wrap:wrap; }
}
